import { getMe, type SessionUser } from './sessionApi';
import { generateUUID } from '@/shared/utils/uuid';

export type SessionStatus = 'unknown' | 'anonymous' | 'authenticated';

interface SessionState {
  status: SessionStatus;
  user: SessionUser | null;
  /** Refresh from /api/auth/me. Broadcasts the resulting state to other tabs. */
  refresh: () => Promise<void>;
  /** Local sign-in commit (e.g. after OAuth callback). Broadcasts. */
  setAuthenticated: (user: SessionUser) => void;
  /** Local sign-out commit (explicit sign-out, forced 401). Broadcasts. */
  setAnonymous: () => void;
  /** Apply an external state change (e.g. another tab's broadcast) without
   *  re-broadcasting. Use only inside the BroadcastChannel handler. */
  applyRemoteState: (status: 'authenticated' | 'anonymous') => Promise<void>;
}

export const useSessionStore = create<SessionState>((set, get) => ({
  status: 'unknown',
  user: null,
  refresh: async () => {
    // A self-hosted build has no auth API. Without this the first refresh
    // throws, the status never leaves 'unknown', and every sign-in surface
    // sits behind a permanent skeleton. Not broadcast: it is a local default,
    // not a server answer.
    if ((import.meta.env.VITE_SELF_HOSTED as string | undefined) === '1') {
      set({ status: 'anonymous', user: null });
      return;
    }
    const next = await refreshFromServer();
    if (!next) return;
    set(next.state);
    broadcastSessionChange(next.broadcastType);
  },
  setAuthenticated: (user) => {
    set({ status: 'authenticated', user });
    broadcastSessionChange('authenticated');
  },
  setAnonymous: () => {
    set({ status: 'anonymous', user: null });
    broadcastSessionChange('anonymous');
  },
  applyRemoteState: async (status) => {
    if (status === 'authenticated') {
      // Another tab signed in. Fetch the user record (we don't trust the
      // broadcast payload — the cookie is the source of truth).
      const next = await refreshFromServer();
      if (next) set(next.state);
    } else if (get().status !== 'anonymous') {
      set({ status: 'anonymous', user: null });
    }
  },
}));

/** Hits /api/auth/me and returns the resulting state, or null on transient error. */
async function refreshFromServer(): Promise<{
  state: { status: SessionStatus; user: SessionUser | null };
  broadcastType: 'authenticated' | 'anonymous';
} | null> {
  try {
    const user = await getMe();
    return user
      ? { state: { status: 'authenticated', user }, broadcastType: 'authenticated' }
      : { state: { status: 'anonymous', user: null }, broadcastType: 'anonymous' };
  } catch {
    // Network error during refresh: don't mutate state. Better to stay where
    // we are and re-try on next visibility flip than spuriously sign out.
    return null;
  }
}

const SESSION_CHANNEL = 'gflt-session';

=== ENGINE HEAD ===
import { apiFetch } from './apiFetch';
import {
  enqueue as outboxEnqueue,
  getDue as outboxGetDue,
  getAll as outboxGetAll,
  markFailure as outboxMarkFailure,
  markSuccess as outboxMarkSuccess,
  rescheduleWithoutAttempt as outboxRescheduleWithoutAttempt,
  type OutboxEntry,
} from './outbox';
import { parseRetryAfter, rateLimitedBackoffMs } from './retryAfter';
import { useSyncStatusStore } from './status';
import type { AdapterChange, SyncAdapter, SyncAdapters, SyncKind } from './adapters/types';
import { PAYLOAD_KEY } from './payloadKey';

type ConflictReason = 'remote-newer' | 'deleted-elsewhere' | 'quota' | 'gave-up';

export type EngineEvent =
  | { type: 'sync-error'; reason: ConflictReason; kind: SyncKind; id: string; message?: string }
  | { type: 'remote-replaced-local'; kind: SyncKind; id: string };

export type EngineEventListener = (event: EngineEvent) => void;

interface EngineState {
  adapters: SyncAdapters;
  unsubscribers: Array<() => void>;
  /** Per-(kind, id) in-flight push promise — serializes writes for the same item. */
  inFlight: Map<string, Promise<void>>;
  /** External listeners (toast surface installs one). */
  listeners: Set<EngineEventListener>;
  drainTimer: ReturnType<typeof setTimeout> | null;
  /** Set to true while `stop()` is tearing down — drainer skips its tail. */
  stopping: boolean;
  /**
   * Per-(kind, id) count of consecutive 429s without a server-provided
   * Retry-After. Drives `rateLimitedBackoffMs`'s exponent. Distinct from
   * `OutboxEntry.attempts` — that field is intentionally not bumped for
   * rate-limit responses so they don't burn the gave-up budget. Cleared
   * on any non-429 outcome for the same item.
   */
  rateLimitedRetries: Map<string, number>;
}

let state: EngineState | null = null;

/** Idempotent. Boot site (PR 4d) calls this on sign-in, `stop()` on sign-out. */
export function start(adapters: SyncAdapters): void {
  if (state !== null) return;
  const s: EngineState = {
    adapters,
    unsubscribers: [],
    inFlight: new Map(),
    listeners: new Set(),
    drainTimer: null,
    stopping: false,
    rateLimitedRetries: new Map(),
  };
  state = s;

  for (const kind of Object.keys(adapters) as SyncKind[]) {
    const adapter = adapters[kind];
    s.unsubscribers.push(
      adapter.subscribe((change) => {
        onLocalChange(s, kind, change).catch((error: unknown) =>
          reportUncaught('onLocalChange', error)
        );
      })
    );
  }

  rehydrate(s).catch((error: unknown) => reportUncaught('rehydrate', error));
}

export function stop(): void {
  if (state === null) return;
  state.stopping = true;
  for (const off of state.unsubscribers) off();
  if (state.drainTimer !== null) clearTimeout(state.drainTimer);
  state.listeners.clear();
  state = null;

